import { PlaneGeometry, Mesh, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

/**
 * Creates a setting-card-2 plane with brushed metal texture.
 * @param {NodeConfig} config - Configuration object.
 * @param {NodeContext} ctx - Context with textureLoader.
 * @returns {Object3D} The mesh with cleanup handler.
 */
export default function createNode(config, ctx) {
  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.needsUpdate = true;

  // Geometry dimensions derived from atlas region aspect ratio (512x320)
  const width = 2; // scene units
  const height = width * (320 / 512); // ≈1.25

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ map: texture });
  const mesh = new Mesh(geometry, material);

  // Apply scene placement
  mesh.position.set(
    config.scenePosition?.x ?? 0,
    config.scenePosition?.y ?? -0.3,
    config.scenePosition?.z ?? 0
  );
  mesh.rotation.set(
    config.sceneRotation?.x ?? 0,
    config.sceneRotation?.y ?? 0,
    config.sceneRotation?.z ?? 0
  );
  mesh.scale.set(
    config.sceneScale?.x ?? 1,
    config.sceneScale?.y ?? 1,
    config.sceneScale?.z ?? 1
  );

  // No interactions or data bindings
  mesh.userData.handlers = {};

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
